import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("POSTGRES_URL");
    private static final String DB_USER = System.getenv("POSTGRES_USER");
    private static final String DB_PASS = System.getenv("POSTGRES_PASS");
    private static final String ADMIN_TOKEN = System.getenv("ADMIN_API_TOKEN");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String patientId = req.getParameter("id");
        String department = req.getParameter("dept");
        String authHeader = req.getHeader("Authorization");

        // Basic auth check - token must be present
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            resp.sendError(401, "Missing authorization");
            return;
        }

        // Input length validation
        if (patientId != null && patientId.length() > 64) {
            resp.sendError(400, "Invalid patient ID length");
            return;
        }
        if (department != null && department.length() > 128) {
            resp.sendError(400, "Invalid department length");
            return;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query with department filter
            String query;
            if (department != null && !department.isEmpty()) {
                query = "SELECT patient_id, name, dob, diagnosis, attending_physician "
                      + "FROM patient_records WHERE department = '" + department + "'";
                if (patientId != null && !patientId.isEmpty()) {
                    query += " AND patient_id = '" + patientId + "'";
                }
            } else {
                query = "SELECT patient_id, name, dob, diagnosis, attending_physician "
                      + "FROM patient_records WHERE patient_id = '" + patientId + "'";
            }

            logger.info("Executing query for dept=" + department + " pid=" + patientId);
            ResultSet rs = stmt.executeQuery(query);

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject record = new JSONObject();
                record.put("patient_id", rs.getString("patient_id"));
                record.put("name", rs.getString("name"));
                record.put("dob", rs.getString("dob"));
                record.put("diagnosis", rs.getString("diagnosis"));
                record.put("attending", rs.getString("attending_physician"));
                results.put(record);
            }

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            logger.severe("Database error: " + e.getMessage());
            // Return generic error to avoid info leakage
            resp.sendError(500, "Internal server error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Admin-only bulk export endpoint
        String authHeader = req.getHeader("Authorization");
        if (authHeader == null || !authHeader.equals("Bearer " + ADMIN_TOKEN)) {
            resp.sendError(403, "Admin access required");
            return;
        }
        // ... bulk export logic omitted for brevity
        resp.setStatus(202);
    }
}
